        nbs={cell for i,j in cells for ds in [(1,0),(-1,0),(0,1),(0,-1)] for cell in [(i+di,j+dj) for di,dj in ds] if 0<=cell[0]<len(g) and 0<=cell[1]<len(g[0]) and cell in s}
        newcells={(i,j) for i,j in cells if not has_neighbor(i,j,nbs)}
